local records={["Core/announcements.lua"]={bytes=12199,hash=168718866,oldBytes=10243,oldHash=509361714,changes={{at=1599,current="-- Native unit APIs may accept a resolvable name as well as a unit token.\010-- Keep the cast's recorded recipient exact; never infer the selected target.\010local function automaticTarget(recipient,owned)\010    local function readable(value)\010        return platform:CanReadValue(value) and (not canaccessvalue or canaccessvalue(value))\010    end\010    if not readable(recipient) or type(recipient)~='string' or recipient=='' or #recipient>512 or recipient:find('[%z\\1-\\31\\127]') then return end\010    local exists,guid=UnitExists,UnitGUID\010    if type(exists)~='function' or type(guid)~='function' then return end\010    local function live()\010        if not owned() then return false end\010        return exists==UnitExists and guid==UnitGUID\010    end\010    local function observe()\010        if not live() then return end\010        local ok,present=pcall(exists,recipient)\010        if not ok or not readable(present) or present~=true or not live() then return end\010        local identified,id=pcall(guid,recipient)\010        if not identified or not readable(id) then return end\010        if canaccessvalue and not canaccessvalue(id) then return end\010        if type(id)~='string' or id=='' or #id>256 or not live() then return end\010        return id\010    end\010    local identity=observe()\010    if not identity then return end\010    return recipient,function()\010        local now=observe()\010        if canaccessvalue and not canaccessvalue(now) then return false end\010        if canaccessvalue and not canaccessvalue(identity) then return false end\010        return now==identity\010    end\010end\010",previous=""},{at=3735,current="    local resolve\010    if config.type~='macro' and targetUnit==nil then\010        resolve=function(tag)\010            local unit,current=automaticTarget(recipient,owned)\010            if unit then return tag=='GROUP' and 'spellrecipient' or unit,current end\010        end\010    end\010    local result\010    if resolve then result=self:evaluateAnnouncementConditionResult(config.conditions,recipient,targetUnit,resolve)\010    else result=self:evaluateAnnouncementConditionResult(config.conditions,recipient,targetUnit) end\010",previous="    local result=self:evaluateAnnouncementConditionResult(config.conditions,recipient,targetUnit)\010"}}},["Core/conditions.lua"]={bytes=23874,hash=18706008,oldBytes=21927,oldHash=4083199220,changes={{at=5804,current="        elseif state.announcementTarget and value.unit=='announcementtarget' then\010            local unit,current=state.announcementTarget(value.type)\010            if not unit or type(current)~='function' or not current() or type(definition.fields)~='table' or definition.fields.unit~='string' then\010                result=outcome('unavailable','cast-recipient-unavailable',path)\010            else\010                -- Contextual units validate fields with the same representative\010                -- player token used by the editor, then evaluate the exact name.\010                local validation=addon.RotationData.CopyData(value);validation.unit='player'\010                local validOk,valid\010                if current() then validOk,valid=callCondition(definition,'valid',validation,cache,start,path,state.context) end\010                if not current() then result=outcome('unavailable','cast-recipient-changed',path)\010                elseif not validOk or not valid then result=outcome('unavailable','invalid-condition-fields',path)\010                else\010                    local input=addon.RotationData.CopyData(value);input.unit=unit\010                    local evalOk,matched,reason=callCondition(definition,'evaluate',input,cache,start,path,state.context)\010                    if not current() then result=outcome('unavailable','cast-recipient-changed',path)\010                    elseif not evalOk then result=outcome('unavailable','condition-callback-error',path)\010                    elseif matched==nil and reason~=nil then result=outcome('unavailable',reason,path)\010                    else result=outcome(matched and 'match' or 'no-match') end\010                end\010            end\010",previous=""},{at=22581,current="function addon:evaluateAnnouncementConditionResult(value, recipient, targetUnit, resolveTarget)\010    local resolved,reason\010    if resolveTarget then\010        if not addon.RotationData.CheckPortable(value) then return outcome('unavailable','invalid-announcement-condition','announcement') end\010        resolved=value\010    else resolved,reason=announcementUnits(value,targetUnit) end\010",previous="function addon:evaluateAnnouncementConditionResult(value, recipient, targetUnit)\010    local resolved,reason=announcementUnits(value,targetUnit)\010"},{at=23034,current="    local result=evaluate(resolved, {announcementRecipient=recipient}, GetTime(), {active={}, count=0, announcementTarget=resolveTarget}, 0, \"announcement\")\010",previous="    local result=evaluate(resolved, {announcementRecipient=recipient}, GetTime(), {active={}, count=0}, 0, \"announcement\")\010"}}},["UI/settings_announces.lua"]={bytes=15083,hash=3295725144,oldBytes=15284,oldHash=3119579411,changes={{at=2141,current="",previous="            p:Text(L['Help.Announces.macro.brief'])\010            p:Text(string.format(L['Macro call: %s'],string.format('/run RM_Annouce(%q,\"mouseover\",nil)',entry.identifier or 'FOO')))\010"},{at=5156,current="            end,current,{persistentOwner=true,announcement=true,announcementTarget=true,title=L['Announcement conditions'],contextLabel=L['Announces']})\010",previous="            end,current,{persistentOwner=true,announcement=true,announcementTarget=entry.type=='macro',title=L['Announcement conditions'],contextLabel=L['Announces']})\010"}}},["Locales/enUS.lua"]={bytes=251886,hash=73360735,oldBytes=251629,oldHash=4170098423,changes={{at=179988,current="L[\"Help.Announces.conditions\"] = \"Optional conditions use the Announcement condition list and All, Any and Not groups. For spell, pet and item announcements, they run when the configured action and event match. For Via Macro, they run when you invoke the saved identifier. Only a matching result allows its message or sound; unavailable data skips the announcement. In Group can check the Spell recipient recorded for this cast, including click casting, without using your selected target. Choose Announcement target to check the spell recipient for automatic entries, or the supplied unit for Via Macro; Whisper uses that same supplied unit. Automatic entries pass the recorded recipient name to native unit queries. A missing or unresolvable recipient skips its required condition; an unrelated selected target is never substituted. Missing or ambiguous required recipients do not match. Apply in the condition editor updates the announcement draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.\"\010",previous="L[\"Help.Announces.conditions\"] = \"Optional conditions use the Announcement condition list and All, Any and Not groups. For spell, pet and item announcements, they run when the configured action and event match. For Via Macro, they run when you invoke the saved identifier. Only a matching result allows its message or sound; unavailable data skips the announcement. In Group can check the Spell recipient recorded for this cast, including click casting, without using your selected target. For Via Macro, choose Announcement target to check the supplied unit; Whisper uses that same unit. Missing or ambiguous required recipients do not match. Apply in the condition editor updates the announcement draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.\"\010"},{at=182461,current="L['Help.Window.navigation'] = 'Choose tabs to browse Rotations, General, Conditions, Functions, Effects, Item Sets, Announces, Profiles and Integrations. The opened panes have their own Help for page controls. Search and filters belong to the current page. Built In entries remain read-only; Duplicate creates an editable copy.'\010",previous="L['Help.Window.navigation'] = 'Choose tabs to browse Rotations, General, Conditions, Functions, Effects, Item Sets, Announces, Profiles and Integrations. Each tab has its own Help for page controls. Search and filters belong to the current page. Built In entries remain read-only; Duplicate creates an editable copy.'\010"}}},["Web/schema/catalog.json"]={bytes=32746,hash=3340804948,oldBytes=32746,oldHash=4145159731,changes={{at=31523,current="5992158fa0a143839b80e7280154d1d72ac0fd7aa09779dabae25a91dad1f6fe",previous="8b73beb0038d2e0a9bc63d5556f1308870d5b8035845486104c3de052003c21f"}}},["Web/catalog/defaults.json"]={bytes=487697,hash=1611187685,oldBytes=487697,oldHash=2937774023,changes={{at=487256,current="b7b0c9763872dffd6f46e59d4af515dc7164daf8dbc1a1d14a74f25babe91c8d",previous="4e46c09a8b543c220990beb5cbf0a9ea203b2fdcf5127f0d3e0a5d3d57e001d2"}}},["tools/check"]={bytes=40111,hash=1154464806,oldBytes=39847,oldHash=93498584,changes={{at=12128,current="            ['lua5.1', 'tests/automatic_announcement_target.lua'],\010            ['luajit', 'tests/automatic_announcement_target.lua'],\010            ['lua5.1', 'tests/condition_invalid_expansion.lua'],\010            ['luajit', 'tests/condition_invalid_expansion.lua'],\010",previous=""}}}}
local function hash(s)local n=5381;for i=1,#s do n=(n*33+s:byte(i))%4294967296 end;return n end
return function(value,path)
 local row=records[path];if not row then return value end
 if #value==row.oldBytes and hash(value)==row.oldHash then return value end
 assert(#value==row.bytes and hash(value)==row.hash,'unrelated complete automatic announcement source: '..path)
 for i=#row.changes,1,-1 do local c=row.changes[i];assert(value:sub(c.at,c.at+#c.current-1)==c.current);value=value:sub(1,c.at-1)..c.previous..value:sub(c.at+#c.current)end
 assert(#value==row.oldBytes and hash(value)==row.oldHash,'automatic announcement predecessor differs: '..path)
 return value
end
